def move_files(apps, old, new):
    """Move each site version's files from the old storage prefix to the new one."""
    from django.core.files.storage import storages

    storage = storages["default"]
    for version in apps.get_model("apiary", "SiteVersion").objects.select_related("site"):
        tail = f"{version.site.project}/{version.site.key}/v{version.number}/"
        for path in version.files:
            source, target = f"{old}/{tail}{path}", f"{new}/{tail}{path}"
            # Safe to run twice: a file already moved is left alone.
            if storage.exists(source) and not storage.exists(target):
                with storage.open(source, "rb") as handle:
                    storage.save(target, ContentFile(handle.read()))
                storage.delete(source)


def to_sites(apps, schema_editor):
    move_files(apps, "pages", "sites")
    apps.get_model("apiary", "DataSnapshot").objects.filter(kind="page").update(kind="site")


def to_pages(apps, schema_editor):
    move_files(apps, "sites", "pages")
    apps.get_model("apiary", "DataSnapshot").objects.filter(kind="site").update(kind="page")


